import sympy as sp

# Define the function to find the smallest integer that can be written as the sum of two different positive cubes
def smallest_integer_with_two_cubes():
    cubes = []
    for i in range(1, 100):
        for j in range(i+1, 100):
            a = i**3
            b = j**3
            if a + b == 1000:
                cubes.append((a, b))
    return min(cubes)

# Find the second smallest integer that can be written as the sum of two positive cubes in two different ways
def second_smallest_integer_with_two_cubes():
    cubes = []
    for i in range(1, 100):
        for j in range(i+1, 100):
            a = i**3
            b = j**3
            if a + b == 1000:
                cubes.append((a, b))
    return min(cubes)

