# Define the function f(n) as per the problem statement
def f(n):
    if n is None:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n % 10 == 4:
        return 0
    if isinstance(n, int):
        return f(n)  # This is a placeholder; we'll handle it in the recursive function
    else:
        return f(n/10) + f(n%10)  # Recursive step

# Function to calculate f(1998)
